const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = { token: localStorage.getItem('splitmate_token'), user: JSON.parse(localStorage.getItem('splitmate_user')||'null'), groups: [], currentGroup: null, expenses: [], balances: null, splitMode: 'equal', editingExpense: null };
const categories = ['Food','Transport','Stay','Shopping','Bills','Entertainment','Other'];
const icons = {Food:'bi-cup-hot',Transport:'bi-train-front',Stay:'bi-house',Shopping:'bi-bag',Bills:'bi-receipt',Entertainment:'bi-ticket-perforated',Other:'bi-three-dots'};
const money = paise => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format((Number(paise)||0)/100);
const initials = name => (name||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const esc = value => String(value??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText = date => date ? new Date(date).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}) : '—';
const route = (path, replace=false) => { if(replace) history.replaceState({},'',path); else history.pushState({},'',path); render(); };
window.addEventListener('popstate', render);
function toast(message, error=false){const node=document.createElement('div');node.className='toast-msg'+(error?' error':'');node.textContent=message;$('#toast-root').append(node);setTimeout(()=>node.remove(),3600);}
async function api(path, options={}) { const headers={'Content-Type':'application/json',...(options.headers||{})};if(state.token)headers.Authorization=`Bearer ${state.token}`;let response;try{response=await fetch('/api'+path,{...options,headers});}catch(e){throw new Error('Cannot reach the API. Check that the SplitMate server is running.');}let body;try{body=await response.json();}catch{throw new Error('The server returned an invalid response.');}if(!response.ok){if(response.status===401&&state.token){logout(false);route('/login',true);}throw new Error(body.message||`Request failed (${response.status})`);}return body.data;}
function saveSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('splitmate_token',data.token);localStorage.setItem('splitmate_user',JSON.stringify(data.user));}
function logout(show=true){state.token=null;state.user=null;localStorage.removeItem('splitmate_token');localStorage.removeItem('splitmate_user');if(show)toast('You have logged out.');route('/login',true);}
function landingPage(){$('#app').innerHTML=`<div style="min-height:100vh;background:#fff"><nav class="d-flex align-items-center justify-content-between px-4 px-lg-5 py-4 border-bottom" style="border-color:var(--line)!important"><div class="brand" style="padding:0"><div class="brand-mark">S</div><div class="brand-title">Split<span>Mate</span></div></div><div class="d-flex align-items-center gap-3"><button class="btn btn-light" id="landing-login">Sign in</button><button class="btn btn-primary" id="landing-register">Get started <i class="bi bi-arrow-right ms-1"></i></button></div></nav><main class="container py-5"><div class="row align-items-center g-5 py-lg-5"><div class="col-lg-6"><div class="eyebrow mb-3">SHARED EXPENSES, MADE SIMPLE</div><h1 style="font-size:clamp(42px,6vw,68px);line-height:1.06;max-width:650px">Split fairly.<br><span style="color:var(--green)">Settle simply.</span></h1><p class="mt-4 mb-4" style="font-size:16px;line-height:1.8;color:var(--muted);max-width:500px">Track group spending, see exactly who owes whom, and make every split transparent. Less awkward money talk, more time together.</p><div class="d-flex gap-3 flex-wrap"><button class="btn btn-primary btn-lg" id="landing-start">Create your free account <i class="bi bi-arrow-up-right ms-1"></i></button><button class="btn btn-outline-secondary btn-lg" id="landing-signin">I already have an account</button></div><div class="d-flex gap-4 mt-5 flex-wrap"><span class="small-muted"><i class="bi bi-check-circle-fill positive me-1"></i> Equal & custom splits</span><span class="small-muted"><i class="bi bi-check-circle-fill positive me-1"></i> Clear balances</span><span class="small-muted"><i class="bi bi-check-circle-fill positive me-1"></i> Paise-level accuracy</span></div></div><div class="col-lg-6"><div style="background:#f5f9f6;border:1px solid var(--line);border-radius:24px;padding:22px;box-shadow:var(--shadow)"><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="small-muted">GROUP OVERVIEW</div><h3 class="fs-5 mt-1 mb-0">Weekend in Goa</h3></div><span class="badge-soft">3 members</span></div><div class="stat-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))"><div class="stat-card"><div class="stat-top">Group spending <span class="stat-icon"><i class="bi bi-wallet2"></i></span></div><div class="stat-value">₹10,250</div><div class="stat-note">Across shared expenses</div></div><div class="stat-card"><div class="stat-top">Your balance <span class="stat-icon"><i class="bi bi-arrow-left-right"></i></span></div><div class="stat-value positive">+₹1,250</div><div class="stat-note">Illustrative interface preview</div></div></div><div class="panel" style="margin:0;box-shadow:none"><div class="panel-head"><div><h2>Suggested settlement</h2><p>Clear the group balance with fewer awkward messages</p></div></div><div class="transfer-card"><div class="transfer-route"><span>Aarav Mehta</span><i class="bi bi-arrow-right arrow"></i><span>Diya Sharma</span></div><div class="transfer-amount">₹850.00</div><span class="small-muted">Preview only — no demo transactions are stored.</span></div><div class="expense-item"><div class="expense-icon"><i class="bi bi-cup-hot"></i></div><div class="expense-main"><strong>Dinner by the beach</strong><small>Paid by Aarav · Food</small></div><div class="expense-amount">₹2,850</div></div></div></div></div></div></main><footer class="text-center py-4 small-muted border-top">SplitMate · Student-built · Shared costs, sorted.</footer></div>`;$('#landing-login').onclick=$('#landing-signin').onclick=()=>route('/login');$('#landing-register').onclick=$('#landing-start').onclick=()=>route('/register');}
function authPage(register=false){$('#app').innerHTML=`<div class="auth-layout"><section class="auth-visual"><div class="brand"><div class="brand-mark">S</div><div><div class="brand-title" style="color:white">Split<span>Mate</span></div><div class="brand-sub" style="color:#b5d0c1">Shared costs, sorted.</div></div></div><div><div class="eyebrow" style="color:#8dd6b1;margin-bottom:18px">LESS MATH. MORE MEMORIES.</div><h1>Good times are better when money is clear.</h1><p>Track shared expenses, understand every split, and settle up without awkward conversations.</p></div><div class="auth-quote">“Fair splits. Clear minds. Better group plans.”</div></section><section class="auth-form-side"><form id="auth-form" class="auth-form"><div class="brand mb-5" style="padding:0"><div class="brand-mark">S</div><div class="brand-title">Split<span>Mate</span></div></div><h2>${register?'Create your account':'Welcome back'}</h2><p>${register?'Start tracking group expenses in a few simple steps.':'Sign in to see where your group stands.'}</p>${register?`<div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="name" required minlength="2" maxlength="60" placeholder="e.g. Jashan Mukheja"></div>`:''}<div class="mb-3"><label class="form-label">Email address</label><input class="form-control" name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><div class="mb-4"><label class="form-label">Password</label><input class="form-control" name="password" type="password" required minlength="${register?8:1}" maxlength="72" autocomplete="${register?'new-password':'current-password'}" placeholder="${register?'At least 8 characters':'Enter your password'}"></div><button class="btn btn-primary w-100" type="submit">${register?'Create account':'Sign in'} <i class="bi bi-arrow-right ms-1"></i></button><div class="auth-switch">${register?'Already have an account?':'New to SplitMate?'} <button type="button" id="auth-switch">${register?'Sign in':'Create an account'}</button></div><p class="small-muted text-center mt-4 mb-0">Your group data is only visible to its members.</p></form></section></div>`;
$('#auth-switch').onclick=()=>route(register?'/login':'/register');$('#auth-form').onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',e.currentTarget);btn.disabled=true;btn.innerHTML='<span class="spinner-border spinner-border-sm"></span> Please wait…';try{const fd=new FormData(e.currentTarget);const data=Object.fromEntries(fd.entries());const result=await api(register?'/auth/register':'/auth/login',{method:'POST',body:JSON.stringify(data)});saveSession(result);toast(register?'Account created. Welcome to SplitMate!':'Welcome back.');route('/dashboard',true);}catch(err){toast(err.message,true);}finally{btn.disabled=false;btn.textContent=register?'Create account':'Sign in';}};}
function shell(content, active='dashboard', title='Dashboard', subtitle='Here’s what’s happening with your groups.'){const u=state.user||{name:'Guest',email:''};$('#app').innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">S</div><div><div class="brand-title">Split<span>Mate</span></div><div class="brand-sub">Shared costs, sorted.</div></div></div><div><div class="nav-label">WORKSPACE</div><nav class="nav-list"><a class="nav-item ${active==='dashboard'?'active':''}" href="/dashboard" data-route="/dashboard"><i class="bi bi-grid-1x2"></i> Overview</a><a class="nav-item ${active==='groups'?'active':''}" href="/groups" data-route="/groups"><i class="bi bi-people"></i> My groups</a><a class="nav-item ${active==='expenses'?'active':''}" href="/expenses" data-route="/expenses"><i class="bi bi-receipt-cutoff"></i> Expense history</a><a class="nav-item ${active==='settlements'?'active':''}" href="/settlements" data-route="/settlements"><i class="bi bi-arrow-left-right"></i> Settlements</a></nav></div><div><div class="nav-label">ACCOUNT</div><nav class="nav-list"><a class="nav-item ${active==='profile'?'active':''}" href="/profile" data-route="/profile"><i class="bi bi-person-circle"></i> Profile & settings</a></nav></div><div class="sidebar-bottom"><div class="help-card"><div class="stat-icon"><i class="bi bi-shield-check"></i></div><strong>Clear money, calm groups.</strong><p>Every split is visible. Every settlement is tracked.</p><span class="small-muted">SplitMate </span></div><a class="nav-item" href="#" id="logout"><i class="bi bi-box-arrow-left"></i> Log out</a></div></aside><main class="main"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="btn btn-light mobile-menu" id="menu-toggle"><i class="bi bi-list"></i></button><div><div class="top-title">${esc(title)}</div><div class="top-sub">${esc(subtitle)}</div></div></div><div class="top-actions"><button class="btn btn-primary d-none d-sm-inline-flex" id="quick-expense"><i class="bi bi-plus-lg me-2"></i>Add expense</button><div class="user-chip"><div class="avatar">${esc(initials(u.name))}</div><div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></div></header><section class="content">${content}</section></main></div>`;
$$('[data-route]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();route(a.dataset.route);}));$('#logout').onclick=e=>{e.preventDefault();logout();};$('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#quick-expense').onclick=()=>route('/expense/new'+(state.currentGroup?`?group=${state.currentGroup._id}`:''));}
function heading(kicker,title,desc,button=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${button}</div>`;}
function stat(label,value,icon,note){return `<article class="stat-card"><div class="stat-top">${label}<span class="stat-icon"><i class="bi ${icon}"></i></span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`;}
function empty(icon,title,desc,button=''){return `<div class="empty-state"><div class="empty-icon"><i class="bi ${icon}"></i></div><h3>${title}</h3><p>${desc}</p>${button}</div>`;}
function groupCard(g){const members=g.members||[];return `<article class="group-card" data-group="${g._id}"><div class="group-card-top"><div class="group-symbol"><i class="bi ${g.type==='Trip'?'bi-airplane':g.type==='Home'?'bi-house':g.type==='College'?'bi-mortarboard':g.type==='Event'?'bi-stars':'bi-people'}"></i></div><span class="pill">${esc(g.type||'Other')}</span></div><h3>${esc(g.name)}</h3><p>${esc(g.description||'A shared space for group expenses.')}</p><div class="group-foot"><div class="member-stack">${members.slice(0,4).map(m=>`<span class="member-dot" title="${esc(m.name)}">${esc(initials(m.name))}</span>`).join('')}${members.length>4?`<span class="member-dot">+${members.length-4}</span>`:''}</div><div class="group-spend">${money(g.totalSpendPaise||0)}</div></div><div class="small-muted mt-2">${members.length} members · ${g.expenseCount||0} expenses</div></article>`;}
function expenseItem(e){const payer=e.payer||{};const group=e.group||{};return `<div class="expense-item"><div class="expense-icon"><i class="bi ${icons[e.category]||icons.Other}"></i></div><div class="expense-main"><strong>${esc(e.title)}</strong><small>${esc(group.name||'Group')} · paid by ${esc(payer.name||'Member')} · ${dateText(e.date)}</small></div><div class="expense-amount">${money(e.amountPaise)}<small>${esc(e.category||'Other')}</small></div></div>`;}
async function dashboard(){shell('<div class="loading"><span class="spinner-border"></span></div>');try{const d=await api('/dashboard');const s=d.summary;const max=Math.max(1,...d.byCategory.map(x=>x.totalPaise));const categoriesHtml=d.byCategory.length?d.byCategory.slice(0,6).map(x=>`<div><div class="bar-label"><span>${esc(x.category)}</span><span>${money(x.totalPaise)}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,x.totalPaise/max*100)}%"></div></div></div>`).join(''):empty('bi-pie-chart','No category data yet','Add an expense to start seeing your spending breakdown.');const recent=d.recentExpenses.length?d.recentExpenses.map(expenseItem).join(''):empty('bi-receipt','Nothing spent yet','Your latest expenses will appear here.','<button class="btn btn-primary" onclick="route(\'/expense/new\')">Add your first expense</button>');const groups=d.groups.length?d.groups.slice(0,3).map(g=>`<div class="expense-item"><div class="expense-icon"><i class="bi bi-people"></i></div><div class="expense-main"><strong>${esc(g.name)}</strong><small>${esc(g.type)} · ${g.members.length} members</small></div><button class="text-link" data-open-group="${g._id}">Open <i class="bi bi-arrow-up-right"></i></button></div>`).join(''):empty('bi-people','No groups yet','Create a group to start tracking shared spending.','<button class="btn btn-primary" onclick="route(\'/groups\')">Create a group</button>');shell(`${heading('YOUR OVERVIEW',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.user.name.split(' ')[0])}.`,'Here’s your group spending at a glance.','<button class="btn btn-primary" onclick="route(\'/groups\')"><i class="bi bi-plus-lg me-1"></i> New group</button>')}<div class="stat-grid">${stat('Total group spending',money(s.totalSpendPaise),'bi-wallet2',`${s.expenseCount} recorded expenses`)}${stat('Your groups',s.groupCount,'bi-people',s.groupCount?'Across your shared spaces':'Create your first group')}${stat('Outstanding you owe',money(s.outstandingPaise),'bi-arrow-up-right-circle',s.outstandingPaise?'Across all your groups':'You are all settled up')}${stat('Expense records',s.expenseCount,'bi-receipt-cutoff','Actual saved expenses')}</div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><div><h2>Recent expenses</h2><p>Latest activity across your groups</p></div><button class="text-link" onclick="route('/expenses')">View all <i class="bi bi-arrow-right"></i></button></div><div class="expense-list">${recent}</div></section><section class="panel"><div class="panel-head"><div><h2>Your groups</h2><p>Spaces you share with other people</p></div><button class="text-link" onclick="route('/groups')">All groups <i class="bi bi-arrow-right"></i></button></div><div class="expense-list">${groups}</div></section></div><div><section class="panel"><div class="panel-head"><div><h2>Spending by category</h2><p>Breakdown from saved expenses</p></div><i class="bi bi-three-dots"></i></div><div class="category-bars">${categoriesHtml}</div></section><section class="panel"><div class="panel-head"><div><h2>Monthly spending</h2><p>Last six months with recorded data</p></div></div>${d.monthly.length?d.monthly.map(m=>`<div class="bar-label mt-3"><span>${new Date(m.month+'-01T00:00:00').toLocaleDateString('en-IN',{month:'short',year:'numeric'})}</span><span>${money(m.totalPaise)}</span></div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(3,m.totalPaise/Math.max(...d.monthly.map(x=>x.totalPaise))*100)}%"></div></div>`).join(''):'<p class="small-muted">No monthly spending data yet.</p>'}</section></div></div>`);$$('[data-open-group]').forEach(b=>b.onclick=()=>route('/groups/'+b.dataset.openGroup));}catch(e){shell(`${empty('bi-cloud-slash','Dashboard could not load',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/dashboard\')">Try again</button>')}`);}}
async function groupsPage(){shell('<div class="loading"><span class="spinner-border"></span></div>','groups','My groups','Create shared spaces and keep every expense organized.');try{const data=await api('/groups');state.groups=data.groups;shell(`${heading('YOUR SPACES','My groups','Trips, roommates, college events — all in one place.','<button class="btn btn-primary" id="create-group"><i class="bi bi-plus-lg me-1"></i> Create group</button>')}<div class="toolbar"><div class="search-box"><i class="bi bi-search"></i><input class="form-control" id="group-search" placeholder="Search your groups…"></div><span class="small-muted">${data.groups.length} groups</span></div><div class="group-grid" id="group-grid">${data.groups.length?data.groups.map(groupCard).join(''):empty('bi-people','Your first group starts here','Create a group and invite registered users to split shared expenses.','<button class="btn btn-primary" id="empty-create">Create a group</button>')}</div>`,'groups','My groups','Create shared spaces and keep every expense organized.');const openCreate=()=>showGroupModal();$('#create-group')?.addEventListener('click',openCreate);$('#empty-create')?.addEventListener('click',openCreate);$('#group-search')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();$$('[data-group]').forEach(card=>card.style.display=card.innerText.toLowerCase().includes(q)?'':'none');});$$('[data-group]').forEach(card=>card.onclick=()=>route('/groups/'+card.dataset.group));}catch(e){shell(empty('bi-cloud-slash','Could not load groups',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/groups\')">Try again</button>'),'groups','My groups');}}
function showGroupModal(){modal('Create a group',`<form id="group-form"><div class="mb-3"><label class="form-label">Group name</label><input class="form-control" name="name" required minlength="2" maxlength="80" placeholder="e.g. Manali trip"></div><div class="mb-3"><label class="form-label">Group type</label><select class="form-select" name="type"><option>Trip</option><option>Home</option><option selected>College</option><option>Event</option><option>Other</option></select></div><div class="mb-3"><label class="form-label">Description (optional)</label><textarea class="form-control" name="description" maxlength="240" rows="2" placeholder="What is this group for?"></textarea></div><button class="btn btn-primary w-100">Create group</button></form>`);$('#group-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const result=await api('/groups',{method:'POST',body:JSON.stringify(data)});closeModal();toast('Group created.');route('/groups/'+result.group._id);}catch(err){toast(err.message,true);}};}
function modal(title,body){$('#modal-root')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="modal-root" class="modal fade" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content" style="border:0;border-radius:16px"><div class="modal-header" style="border-color:var(--line)"><h5 class="modal-title">${title}</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-4">${body}</div></div></div></div>`);const m=new bootstrap.Modal($('#modal-root'));m.show();$('#modal-root').addEventListener('hidden.bs.modal',()=>$('#modal-root')?.remove());window._splitModal=m;}
function closeModal(){window._splitModal?.hide();}
async function groupDetail(groupId){shell('<div class="loading"><span class="spinner-border"></span></div>','groups','Group details');try{const [{group,totalSpendPaise,expenseCount},exData,balData,settleData]=await Promise.all([api('/groups/'+groupId),api('/groups/'+groupId+'/expenses'),api('/groups/'+groupId+'/balances'),api('/groups/'+groupId+'/settlements')]);state.currentGroup=group;state.expenses=exData.expenses;state.balances=balData;const members=group.members||[];const netById=new Map(balData.members.map(m=>[m.user.id,m.netPaise]));const expHtml=exData.expenses.length?exData.expenses.map(e=>`<tr><td><div class="d-flex align-items-center gap-2"><span class="expense-icon" style="width:32px;height:32px"><i class="bi ${icons[e.category]||icons.Other}"></i></span><div><strong>${esc(e.title)}</strong><div class="small-muted">${dateText(e.date)}</div></div></div></td><td>${esc(e.payer?.name||'—')}</td><td><span class="pill">${esc(e.category)}</span></td><td class="fw-bold">${money(e.amountPaise)}</td><td><button class="btn btn-sm btn-light" data-expense="${e._id}">Details</button></td></tr>`).join(''):'<tr><td colspan="5">'+empty('bi-receipt','No expenses yet','Add the first expense to start calculating balances.')+'</td></tr>';const balances=balData.members.map(m=>`<div class="balance-row"><div class="avatar">${esc(initials(m.user.name))}</div><div class="balance-name"><strong>${esc(m.user.name)} ${m.user.id===group.owner._id?'· Owner':''}</strong><small>${m.netPaise>0?'should receive':m.netPaise<0?'owes the group':'settled up'}</small></div><div class="balance-value ${m.netPaise>0?'positive':m.netPaise<0?'negative':''}">${money(Math.abs(m.netPaise))}</div></div>`).join('');const transfers=balData.transfers.length?balData.transfers.map(t=>{const from=members.find(m=>m._id===t.from)||members.find(m=>m.id===t.from);const to=members.find(m=>m._id===t.to)||members.find(m=>m.id===t.to);return `<div class="transfer-card"><div class="transfer-route"><span>${esc(from?.name||'Member')}</span><i class="bi bi-arrow-right arrow"></i><span>${esc(to?.name||'Member')}</span></div><div class="transfer-amount">${money(t.amountPaise)}</div><button class="btn btn-sm btn-primary" data-settle-from="${t.from}" data-settle-to="${t.to}" data-settle-amount="${t.amountPaise}">Record settlement</button></div>`;}).join(''):empty('bi-check2-circle','All settled up','There are no outstanding balances in this group.');shell(`${heading(esc(group.type||'GROUP'),esc(group.name),esc(group.description||'Manage expenses, understand balances, and settle fairly.'),'<button class="btn btn-primary" id="add-group-expense"><i class="bi bi-plus-lg me-1"></i> Add expense</button>')}<div class="d-flex flex-wrap gap-2 mb-4"><button class="btn btn-outline-secondary" id="add-member"><i class="bi bi-person-plus me-1"></i> Add member</button><button class="btn btn-outline-secondary" id="group-expenses-export"><i class="bi bi-download me-1"></i> Export CSV</button><button class="btn btn-outline-secondary" id="delete-group"><i class="bi bi-trash me-1"></i> Delete group</button></div><div class="stat-grid">${stat('Total spending',money(totalSpendPaise),'bi-wallet2',`${expenseCount} expenses recorded`)}${stat('Group members',members.length,'bi-people','Registered SplitMate users')}${stat('Suggested transfers',balData.transfers.length,'bi-arrow-left-right','Greedy settlement suggestions')}${stat('Confirmed settlements',settleData.settlements.length,'bi-check-circle','Recorded payments')}</div><div class="detail-grid"><div><section class="panel"><div class="panel-head"><div><h2>Expense history</h2><p>Every expense and who paid</p></div><button class="text-link" id="all-group-expenses">View history</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Expense</th><th>Paid by</th><th>Category</th><th>Amount</th><th></th></tr></thead><tbody>${expHtml}</tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Group members</h2><p>Balances include recorded expenses and settlements</p></div></div>${balances}</section></div><div><section class="panel"><div class="panel-head"><div><h2>Smart settlement</h2><p>Practical transfers calculated from net balances</p></div><i class="bi bi-lightning-charge"></i></div>${transfers}<p class="small-muted mt-3">Greedy matching is practical, but is not guaranteed to find the global minimum number of transfers.</p></section><section class="panel"><div class="panel-head"><div><h2>Confirmed settlements</h2><p>Recorded transfers in this group</p></div></div>${settleData.settlements.length?settleData.settlements.map(s=>`<div class="expense-item"><div class="expense-icon"><i class="bi bi-check2"></i></div><div class="expense-main"><strong>${esc(s.from.name)} → ${esc(s.to.name)}</strong><small>${dateText(s.createdAt)}</small></div><div class="expense-amount">${money(s.amountPaise)}</div></div>`).join(''): '<p class="small-muted">No settlements recorded yet.</p>'}</section></div></div>`,'groups',group.name,'Group details and settlement');$('#add-group-expense').onclick=()=>route('/expense/new?group='+groupId);$('#add-member').onclick=()=>showAddMember(group);$('#all-group-expenses').onclick=()=>route('/expenses?group='+groupId);$('#delete-group').onclick=async()=>{if(!confirm('Delete this group and all its expenses and settlements? This cannot be undone.'))return;try{await api('/groups/'+groupId,{method:'DELETE'});toast('Group deleted.');route('/groups');}catch(e){toast(e.message,true);}};$('#group-expenses-export').onclick=()=>downloadCSV(exData.expenses,`${group.name}-expenses.csv`);$$('[data-expense]').forEach(b=>b.onclick=()=>route('/expenses/'+b.dataset.expense));$$('[data-settle-from]').forEach(b=>b.onclick=()=>showSettlementForm(groupId,b.dataset.settleFrom,b.dataset.settleTo,Number(b.dataset.settleAmount)));}catch(e){shell(empty('bi-cloud-slash','Could not load this group',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/groups\')">Back to groups</button>'),'groups','Group details');}}
function showAddMember(group){modal('Add a group member',`<p class="small-muted mb-3">They must already have a SplitMate account. Search by their email address or name.</p><form id="member-form"><div class="mb-3"><label class="form-label">Registered email address</label><input class="form-control" name="email" type="email" required placeholder="friend@example.com"></div><button class="btn btn-primary w-100">Add member</button></form>`);$('#member-form').onsubmit=async e=>{e.preventDefault();try{await api(`/groups/${group._id}/members`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast('Member added.');groupDetail(group._id);}catch(err){toast(err.message,true);}};}
function showSettlementForm(groupId,from,to,maxAmount){const group=state.currentGroup;const f=group.members.find(m=>m._id===from)||group.members.find(m=>m.id===from);const t=group.members.find(m=>m._id===to)||group.members.find(m=>m.id===to);modal('Record a settlement',`<p class="small-muted">Confirm only after the money has actually changed hands.</p><form id="settlement-form"><div class="mb-3"><label class="form-label">From</label><input class="form-control" value="${esc(f?.name||'Member')}" disabled></div><div class="mb-3"><label class="form-label">To</label><input class="form-control" value="${esc(t?.name||'Member')}" disabled></div><div class="mb-3"><label class="form-label">Amount (₹)</label><input class="form-control" name="amount" type="number" min="0.01" max="${maxAmount/100}" step="0.01" value="${(maxAmount/100).toFixed(2)}" required></div><div class="mb-3"><label class="form-label">Note (optional)</label><input class="form-control" name="note" maxlength="200" placeholder="Paid via UPI"></div><button class="btn btn-primary w-100">Confirm settlement</button></form>`);$('#settlement-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api(`/groups/${groupId}/settlements`,{method:'POST',body:JSON.stringify({from,to,...d})});closeModal();toast('Settlement recorded.');groupDetail(groupId);}catch(err){toast(err.message,true);}};}
function downloadCSV(expenses,filename){const rows=[['Title','Amount INR','Payer','Category','Date','Participants','Shares INR'],...expenses.map(e=>[e.title,(e.amountPaise/100).toFixed(2),e.payer?.name||'',e.category,new Date(e.date).toISOString().slice(0,10),(e.participants||[]).map(p=>p.name).join('; '),(e.shares||[]).map(s=>`${s.user?.name||'Member'}: ${(s.amountPaise/100).toFixed(2)}`).join('; ')])];const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
async function expenseForm(editId=null){state.editingExpense=editId;const params=new URLSearchParams(location.search);let groupId=params.get('group');let expense=null;if(editId){try{const d=await api('/expenses/'+editId);expense=d.expense;groupId=String(expense.group?._id||expense.group);}catch(e){toast(e.message,true);route('/expenses');return;}}let groups;try{groups=(await api('/groups')).groups;state.groups=groups;}catch(e){shell(empty('bi-cloud-slash','Could not load groups',esc(e.message)),'expenses','Add expense');return;}if(!groups.length){shell(`${heading('EXPENSES','Add an expense','Expenses belong to a group.')}${empty('bi-people','Create a group first','You need a group before recording shared expenses.','<button class="btn btn-primary" onclick="route(\'/groups\')">Go to groups</button>')}`,'expenses','Add expense');return;}if(!groupId||!groups.some(g=>g._id===groupId))groupId=groups[0]._id;const group=groups.find(g=>g._id===groupId);const participants=expense?(expense.participants||[]).map(p=>String(p._id||p)):(group.members||[]).map(m=>m._id);const payer=String(expense?.payer?._id||expense?.payer||state.user.id||'');const isCustom=!!expense?.shares;state.splitMode='equal';shell(`${heading('EXPENSES',editId?'Edit expense':'Add an expense',editId?'Update the details and split.':'Record who paid and how the cost should be shared.')}<form class="form-card" id="expense-form"><div class="form-grid"><div class="field-full"><label class="form-label">Expense title</label><input class="form-control" name="title" required minlength="2" maxlength="120" value="${esc(expense?.title||'')}" placeholder="e.g. Dinner at the cafe"></div><div><label class="form-label">Total amount (₹)</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required value="${expense?(expense.amountPaise/100):''}" placeholder="0.00"></div><div><label class="form-label">Category</label><select class="form-select" name="category">${categories.map(c=>`<option ${expense?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div><label class="form-label">Group</label><select class="form-select" name="group" id="expense-group">${groups.map(g=>`<option value="${g._id}" ${g._id===groupId?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><div><label class="form-label">Date</label><input class="form-control" name="date" type="date" required value="${expense?new Date(expense.date).toISOString().slice(0,10):new Date().toISOString().slice(0,10)}"></div><div><label class="form-label">Who paid?</label><select class="form-select" name="payer" id="expense-payer">${group.members.map(m=>`<option value="${m._id}" ${(payer===m._id||(!expense&&m._id===state.user.id))?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><div class="field-full"><label class="form-label">Split between</label><div id="participant-options" class="d-flex flex-wrap gap-3">${group.members.map(m=>`<label class="d-flex align-items-center gap-2 small"><input class="form-check-input participant-check" type="checkbox" value="${m._id}" ${participants.includes(m._id)?'checked':''}> ${esc(m.name)}</label>`).join('')}</div><div class="small-muted mt-2">The payer can be included or excluded as a participant depending on who benefited from the expense.</div></div><div class="field-full"><label class="form-label">How should the cost be split?</label><div class="split-options"><button type="button" class="split-option active" data-mode="equal">Equal split</button><button type="button" class="split-option" data-mode="custom">Custom amounts</button></div><div id="share-editor"></div></div><div class="field-full"><label class="form-label">Note (optional)</label><textarea class="form-control" name="note" rows="2" maxlength="500" placeholder="Add a little context…">${esc(expense?.note||'')}</textarea></div></div><div class="d-flex justify-content-between gap-3 mt-4"><button type="button" class="btn btn-outline-secondary" id="cancel-expense">Cancel</button><button type="submit" class="btn btn-primary">${editId?'Save changes':'Save expense'} <i class="bi bi-check2 ms-1"></i></button></div></form>`,'expenses',editId?'Edit expense':'Add expense');
const form=$('#expense-form');let customMode=false;const selected=()=>$$('.participant-check:checked').map(c=>c.value);function drawShares(){const ids=selected();const amount=Math.round(Number($('[name=amount]',form).value||0)*100);if(!ids.length){$('#share-editor').innerHTML='<p class="small-muted">Select at least one participant.</p>';return;}if(!customMode){const base=Math.floor(amount/ids.length),rem=amount%ids.length;$('#share-editor').innerHTML=`<div class="p-3 rounded-3" style="background:#f5f9f6"><div class="d-flex justify-content-between"><span class="small-muted">Each person pays</span><strong>${money(base+(rem?1:0))}${rem?'*':''}</strong></div><p class="small-muted mt-2 mb-0">${ids.length} participants · Any remainder is distributed one paise at a time. ${rem?'*Some shares differ by ₹0.01 to make the total exact.':''}</p></div>`;}else{$('#share-editor').innerHTML=`${ids.map(uid=>{const m=group.members.find(m=>m._id===uid);const old=expense?.shares?.find(s=>String(s.user?._id||s.user)===uid);return `<div class="share-row"><span class="small">${esc(m?.name||'Member')}</span><input class="form-control custom-share" type="number" min="0" step="0.01" data-user="${uid}" value="${old?(old.amountPaise/100).toFixed(2):(amount/100/ids.length).toFixed(2)}" required></div>`;}).join('')}<div class="share-total"><span>Shares total</span><span id="share-total">${money(amount)}</span></div><div id="share-warning" class="small-muted mt-2"></div>`;$$('.custom-share').forEach(inp=>inp.oninput=updateShareTotal);updateShareTotal();}}function updateShareTotal(){const amount=Math.round(Number($('[name=amount]',form).value||0)*100);const total=$$('.custom-share').reduce((s,i)=>s+Math.round(Number(i.value||0)*100),0);$('#share-total').textContent=money(total);$('#share-warning').textContent=total===amount?'Shares match the total.':`Shares differ by ${money(Math.abs(amount-total))}.`;$('#share-warning').className='small-muted mt-2 '+(total===amount?'positive':'negative');}
$$('[data-mode]').forEach(b=>b.onclick=()=>{customMode=b.dataset.mode==='custom';$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));drawShares();});$$('.participant-check').forEach(c=>c.onchange=drawShares);$('[name=amount]',form).oninput=()=>{if(customMode)updateShareTotal();else drawShares();};$('#expense-group').onchange=()=>{const g=groups.find(g=>g._id===$('#expense-group').value);$('#participant-options').innerHTML=g.members.map(m=>`<label class="d-flex align-items-center gap-2 small"><input class="form-check-input participant-check" type="checkbox" value="${m._id}" checked> ${esc(m.name)}</label>`).join('');$('#expense-payer').innerHTML=g.members.map(m=>`<option value="${m._id}">${esc(m.name)}</option>`).join('');$$('.participant-check').forEach(c=>c.onchange=drawShares);drawShares();};$('#cancel-expense').onclick=()=>route(editId?'/expenses/'+editId:groupId?'/groups/'+groupId:'/expenses');drawShares();form.onsubmit=async e=>{e.preventDefault();const btn=$('button[type=submit]',form);const amount=Math.round(Number($('[name=amount]',form).value)*100);const ids=selected();if(!ids.length){toast('Select at least one participant.',true);return;}let shares;if(customMode){shares=$$('.custom-share').map(inp=>({user:inp.dataset.user,amountPaise:Math.round(Number(inp.value)*100)}));if(shares.reduce((s,x)=>s+x.amountPaise,0)!==amount){toast('Custom shares must equal the total amount exactly.',true);return;}}const data={title:$('[name=title]',form).value,amount:amount/100,category:$('[name=category]',form).value,group:$('#expense-group').value,date:$('[name=date]',form).value,payer:$('#expense-payer').value,participants:ids,note:$('[name=note]',form).value,...(customMode?{shares}:{})};btn.disabled=true;try{const result=await api(editId?'/expenses/'+editId:`/groups/${data.group}/expenses`,{method:editId?'PATCH':'POST',body:JSON.stringify(data)});toast(editId?'Expense updated.':'Expense saved.');route('/expenses/'+result.expense._id,true);}catch(err){toast(err.message,true);}finally{btn.disabled=false;}};}
async function expensesPage(){const params=new URLSearchParams(location.search);const groupId=params.get('group');shell('<div class="loading"><span class="spinner-border"></span></div>','expenses','Expense history');try{let groups=(await api('/groups')).groups;state.groups=groups;let selectedGroup=groupId||'';const load=async()=>{const all=[];const target=selectedGroup?[selectedGroup]:groups.map(g=>g._id);for(const gid of target){try{const data=await api(`/groups/${gid}/expenses`);const g=groups.find(x=>x._id===gid);all.push(...data.expenses.map(e=>({...e,group:{name:g?.name||'Group',_id:gid}})));}catch(e){if(selectedGroup)throw e;}}return all.sort((a,b)=>new Date(b.date)-new Date(a.date));};let expenses=await load();const renderTable=()=>{const q=($('#expense-search')?.value||'').toLowerCase(),cat=$('#expense-category')?.value||'',from=$('#expense-from')?.value||'',to=$('#expense-to')?.value||'';const filtered=expenses.filter(e=>(!q||`${e.title} ${e.payer?.name} ${e.group.name}`.toLowerCase().includes(q))&&(!cat||e.category===cat)&&(!from||e.date.slice(0,10)>=from)&&(!to||e.date.slice(0,10)<=to));$('#expense-table-body').innerHTML=filtered.length?filtered.map(e=>`<tr><td><div class="d-flex align-items-center gap-2"><span class="expense-icon" style="width:34px;height:34px"><i class="bi ${icons[e.category]||icons.Other}"></i></span><div><strong>${esc(e.title)}</strong><div class="small-muted">${esc(e.group.name)}</div></div></div></td><td>${esc(e.payer?.name||'—')}</td><td>${esc(e.category)}</td><td>${dateText(e.date)}</td><td class="fw-bold">${money(e.amountPaise)}</td><td><button class="btn btn-sm btn-light" data-open-expense="${e._id}">Open</button></td></tr>`).join(''):`<tr><td colspan="6">${empty('bi-search','No matching expenses','Try changing the search or filters.')}</td></tr>`;$$('[data-open-expense]').forEach(b=>b.onclick=()=>route('/expenses/'+b.dataset.openExpense));$('#expense-count').textContent=`${filtered.length} expenses`;};shell(`${heading('YOUR RECORDS','Expense history','Search, filter and inspect expenses across your groups.','<button class="btn btn-primary" onclick="route(\'/expense/new\')"><i class="bi bi-plus-lg me-1"></i> Add expense</button>')}<div class="toolbar"><div class="search-box"><i class="bi bi-search"></i><input class="form-control" id="expense-search" placeholder="Search title, payer or group…"></div><select class="form-select" style="max-width:155px" id="expense-category"><option value="">All categories</option>${categories.map(c=>`<option>${c}</option>`).join('')}</select><select class="form-select" style="max-width:180px" id="expense-group-filter"><option value="">All groups</option>${groups.map(g=>`<option value="${g._id}" ${selectedGroup===g._id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><div class="toolbar"><input class="form-control" style="max-width:170px" type="date" id="expense-from" aria-label="From date"><span class="small-muted">to</span><input class="form-control" style="max-width:170px" type="date" id="expense-to" aria-label="To date"><button class="btn btn-outline-secondary" id="clear-filters">Clear filters</button><button class="btn btn-outline-secondary ms-auto" id="export-expenses"><i class="bi bi-download me-1"></i> Export CSV</button><span class="small-muted" id="expense-count"></span></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>Expense</th><th>Paid by</th><th>Category</th><th>Date</th><th>Amount</th><th></th></tr></thead><tbody id="expense-table-body"></tbody></table></div></section>`,'expenses','Expense history','Browse expenses across all groups.');$$('#expense-search, #expense-category, #expense-from, #expense-to').forEach(el=>el.addEventListener('input',renderTable));$('#expense-group-filter').onchange=()=>{route('/expenses'+($('#expense-group-filter').value?'?group='+$('#expense-group-filter').value:''));};$('#clear-filters').onclick=()=>{$('#expense-search').value='';$('#expense-category').value='';$('#expense-from').value='';$('#expense-to').value='';renderTable();};$('#export-expenses').onclick=()=>downloadCSV(expenses,'splitmate-expenses.csv');renderTable();}catch(e){shell(empty('bi-cloud-slash','Could not load expenses',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/expenses\')">Try again</button>'),'expenses','Expense history');}}
async function expenseDetail(expenseId){shell('<div class="loading"><span class="spinner-border"></span></div>','expenses','Expense details');try{const {expense:e}=await api('/expenses/'+expenseId);const gId=String(e.group?._id||e.group);const shares=e.shares||[];const total=shares.reduce((s,x)=>s+x.amountPaise,0);const canEdit=String(e.createdBy?._id||e.createdBy)===state.user.id;const detailRows=shares.map(s=>`<div class="calc-row"><span>${esc(s.user?.name||'Member')} <span class="small-muted">(${(s.amountPaise/e.amountPaise*100||0).toFixed(1)}%)</span></span><strong>${money(s.amountPaise)}</strong></div>`).join('');shell(`${heading('EXPENSE DETAIL',esc(e.title),`${esc(e.category)} · Added ${dateText(e.createdAt)}`,`<button class="btn btn-outline-secondary" onclick="route('/groups/${gId}')"><i class="bi bi-arrow-left me-1"></i> Back to group</button>`)}<div class="detail-grid"><div><div class="detail-hero"><div class="muted-light">TOTAL EXPENSE</div><div class="amount">${money(e.amountPaise)}</div><div class="detail-meta"><span><i class="bi bi-person"></i> Paid by ${esc(e.payer?.name||'Member')}</span><span><i class="bi bi-calendar3"></i> ${dateText(e.date)}</span><span><i class="bi bi-tag"></i> ${esc(e.category)}</span></div></div><section class="panel"><div class="panel-head"><div><h2>Split breakdown</h2><p>Every participant’s share of this expense</p></div><span class="badge-soft">${shares.length} participants</span></div>${detailRows}<div class="calc-row" style="border-top:1px solid var(--line);font-weight:800"><span>Total shares</span><strong>${money(total)}</strong></div><div class="small-muted mt-3">${total===e.amountPaise?'✓ Shares match the total exactly.':'Warning: stored shares do not match the expense total.'} Equal split remainder is distributed in whole paise.</div></section></div><div><section class="panel"><div class="panel-head"><div><h2>Expense transparency</h2><p>Who paid, who participated, and why</p></div></div><div class="calc-row"><span>Paid by</span><strong>${esc(e.payer?.name||'Member')}</strong></div><div class="calc-row"><span>Expense amount</span><strong>${money(e.amountPaise)}</strong></div><div class="calc-row"><span>Participants</span><strong>${(e.participants||[]).length}</strong></div><div class="calc-row"><span>Average share</span><strong>${money(Math.floor(e.amountPaise/Math.max(1,shares.length)))}</strong></div><div class="calc-row"><span>Created by</span><strong>${esc(e.createdBy?.name||'Member')}</strong></div>${e.note?`<div class="mt-3"><div class="small-muted mb-1">NOTE</div><p class="mb-0">${esc(e.note)}</p></div>`:''}</section><section class="panel"><div class="panel-head"><div><h2>Actions</h2><p>Changes update the group’s balances</p></div></div>${canEdit?`<button class="btn btn-primary w-100 mb-2" id="edit-expense"><i class="bi bi-pencil me-1"></i> Edit expense</button><button class="btn btn-outline-secondary w-100" id="delete-expense"><i class="bi bi-trash me-1"></i> Delete expense</button>`:'<p class="small-muted">Only the expense creator or group owner can edit or delete this record.</p>'}</section></div></div>`,'expenses','Expense details','Full calculation breakdown for this expense.');$('#edit-expense')?.addEventListener('click',()=>route('/expenses/'+expenseId+'/edit'));$('#delete-expense')?.addEventListener('click',async()=>{if(!confirm('Delete this expense? Group balances will be recalculated.'))return;try{await api('/expenses/'+expenseId,{method:'DELETE'});toast('Expense deleted.');route('/groups/'+gId);}catch(err){toast(err.message,true);}});}catch(e){shell(empty('bi-exclamation-circle','Expense not found',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/expenses\')">Back to expenses</button>'),'expenses','Expense details');}}
async function settlementsPage(){shell('<div class="loading"><span class="spinner-border"></span></div>','settlements','Settlements');try{const groups=(await api('/groups')).groups;const details=await Promise.all(groups.map(async g=>{const [b,s]=await Promise.all([api(`/groups/${g._id}/balances`),api(`/groups/${g._id}/settlements`)]);return {group:g,balances:b,settlements:s.settlements};}));const transferCount=details.reduce((s,d)=>s+d.balances.transfers.length,0);shell(`${heading('SETTLE UP','Smart settlements','Clear outstanding balances with practical transfer suggestions.')}<div class="stat-grid">${stat('Active groups',groups.length,'bi-people','Groups you belong to')}${stat('Suggested transfers',transferCount,'bi-arrow-left-right','Across all groups')}${stat('Recorded payments',details.reduce((s,d)=>s+d.settlements.length,0),'bi-check-circle','Confirmed settlement records')}${stat('Groups fully settled',details.filter(d=>!d.balances.transfers.length).length,'bi-check2-circle','No outstanding transfers')}</div>${details.length?details.map(d=>`<section class="panel"><div class="panel-head"><div><h2>${esc(d.group.name)}</h2><p>${d.balances.members.length} members · ${d.balances.transfers.length} suggested transfers</p></div><button class="text-link" onclick="route('/groups/${d.group._id}')">Open group <i class="bi bi-arrow-right"></i></button></div>${d.balances.transfers.length?d.balances.transfers.map(t=>{const from=d.group.members.find(m=>m._id===t.from),to=d.group.members.find(m=>m._id===t.to);return `<div class="transfer-card"><div class="transfer-route"><span>${esc(from?.name||'Member')}</span><i class="bi bi-arrow-right arrow"></i><span>${esc(to?.name||'Member')}</span></div><div class="transfer-amount">${money(t.amountPaise)}</div><button class="btn btn-sm btn-primary" data-global-settle="${d.group._id}" data-from="${t.from}" data-to="${t.to}" data-amount="${t.amountPaise}">Record settlement</button></div>`;}).join(''):empty('bi-check2-circle','Everyone is settled','No transfers are currently needed in this group.')}<div class="small-muted mt-3">Suggestions use a greedy balance-matching algorithm; they are not guaranteed to minimize transaction count globally.</div></section>`).join(''):empty('bi-people','No groups yet','Create a group before managing settlements.','<button class="btn btn-primary" onclick="route(\'/groups\')">Create group</button>')}`,'settlements','Settlements','Suggestions and confirmed transfers.');$$('[data-global-settle]').forEach(b=>{b.onclick=()=>{state.currentGroup=details.find(d=>d.group._id===b.dataset.globalSettle).group;showSettlementForm(b.dataset.globalSettle,b.dataset.from,b.dataset.to,Number(b.dataset.amount));};});}catch(e){shell(empty('bi-cloud-slash','Could not load settlements',esc(e.message),'<button class="btn btn-primary" onclick="route(\'/settlements\')">Try again</button>'),'settlements','Settlements');}}
async function profilePage(){shell('<div class="loading"><span class="spinner-border"></span></div>','profile','Profile & settings');try{const {user}=await api('/auth/me');state.user={...state.user,...user};shell(`${heading('ACCOUNT','Profile & settings','Manage your SplitMate account details.')}<section class="panel" style="max-width:760px"><div class="panel-head"><div><h2>Your profile</h2><p>Your account details used across groups</p></div><div class="avatar" style="width:48px;height:48px;font-size:15px">${esc(initials(user.name))}</div></div><form id="profile-form"><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="name" required minlength="2" maxlength="60" value="${esc(user.name)}"></div><div class="mb-4"><label class="form-label">Email address</label><input class="form-control" value="${esc(user.email)}" disabled><div class="small-muted mt-1">Email changes are not supported in this version.</div></div><button class="btn btn-primary">Save changes</button></form></section><section class="panel danger-zone" style="max-width:760px"><h3 class="fs-6">Session</h3><p class="small-muted">Log out to end this browser session. Your group records remain saved.</p><button class="btn btn-outline-secondary" id="profile-logout">Log out</button></section><section class="panel" style="max-width:760px"><h3 class="fs-6">About SplitMate</h3><p class="small-muted mb-1">Built with vanilla JavaScript, Express, MongoDB and Mongoose.</p><p class="small-muted mb-0">Money is stored as integer paise. Settlement suggestions use a greedy matching algorithm.</p></section>`,'profile','Profile & settings','Manage your account.');$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const data=Object.fromEntries(new FormData(e.target));const result=await api('/users/me',{method:'PATCH',body:JSON.stringify(data)});state.user=result.user;localStorage.setItem('splitmate_user',JSON.stringify(state.user));toast('Profile updated.');profilePage();}catch(err){toast(err.message,true);}};$('#profile-logout').onclick=()=>logout();}catch(e){shell(empty('bi-person-x','Could not load profile',esc(e.message)),'profile','Profile & settings');}}
async function render(){const path=location.pathname;if(!state.token){if(path==='/register')return authPage(true);if(path==='/login')return authPage(false);if(path==='/')return landingPage();return route('/login',true);}if(!state.user){try{const d=await api('/auth/me');state.user=d.user;}catch{return authPage(false);}}if(path==='/'||path==='/login'||path==='/register')return route('/dashboard',true);if(path==='/dashboard')return dashboard();if(path==='/groups')return groupsPage();if(/^\/groups\/[^/]+$/.test(path))return groupDetail(path.split('/')[2]);if(path==='/expense/new')return expenseForm();if(/^\/expenses\/[^/]+\/edit$/.test(path))return expenseForm(path.split('/')[2]);if(path==='/expenses')return expensesPage();if(/^\/expenses\/[^/]+$/.test(path))return expenseDetail(path.split('/')[2]);if(path==='/settlements')return settlementsPage();if(path==='/profile')return profilePage();return route('/dashboard',true);}
// Keep the app navigable when clicking ordinary internal links and support browser history.
document.addEventListener('click',e=>{const a=e.target.closest('a[data-route]');if(a){e.preventDefault();route(a.dataset.route);}});
(async()=>{if(state.token){try{const d=await api('/auth/me');state.user=d.user;}catch{state.token=null;state.user=null;localStorage.removeItem('splitmate_token');localStorage.removeItem('splitmate_user');}}await render();})();
